[4450] = { en = "Ledger from Tanaris", tier = 4,
  t = "Grootboek uit Tanaris",
  d = "O, weet je wat? Daar denk ik ineens aan.$B$BWil je een klusje afmaken dat ik aannam toen ik in Tanaris was? Het is makkelijk...$B$BKrinkle Goodsteel in Gadgetzan zocht wat spullen. Die vind je hier in Searing Gorge en op een paar andere plekken. Misschien kun je de lijst bekijken en alles daarna naar hem brengen?$B$BIk schuif zijn grootboek wel onder de deur door als je wilt. Neem dat mee, en breng hem de spullen die hij wil als je alles hebt verzameld.",
  o = "Neem het exemplaar van Goodsteel's Ledger mee. Zoek de spullen die erin staan en ga daarna naar Krinkle Goodsteel in Tanaris.",
  p = "Ja, ja? Wat kan ik voor je doen, $r? Ik heb het erg druk, en veel klanten willen mijn diensten. Misschien kun jij het sneller maken. Ik wil niet onbeleefd zijn, maar ik heb gewoon geen tijd als ik al mijn werk wil inhalen.",
  c = "O, je hebt een deel van het werk gedaan waar ik om vroeg. Uitstekend. En ik dacht nog wel dat je me zou vragen om iets voor je te maken.$B$BDit is allemaal perfect... en alles is er. Dank je, $c.$B$BMisschien kan het geen kwaad om je wat te belonen... hmm, wat zou jij handig vinden?",
  g = { {"grootboek", "ledger"}, {"ineens", "suddenly"}, {"klusje", "little job (klus)"}, {"aannam", "took on, accepted (aannemen)"}, {"schuif", "slide (schuiven)"}, {"exemplaar", "copy"}, {"klanten", "patrons, customers (klant)"}, {"diensten", "services (dienst)"}, {"onbeleefd", "rude, impolite"}, {"inhalen", "to catch up (on)"}, {"het kan geen kwaad", "it wouldn't hurt"}, {"belonen", "to reward"} },
},

[2990] = { en = "Thadius Grimshade", tier = 4,
  t = "Thadius Grimshade",
  d = "Breng deze veer naar Thadius Grimshade, de waarzegger. Hij heeft Aerie Peak jaren geleden verlaten om duisterdere kennis te zoeken, maar in zijn hart is hij nog steeds een Wildhammer!$B$BEn misschien kunnen zijn talenten ons helpen om Sharpbeak te vinden.$B$BDeze veer komt uit het nest waar het griffioenjong slaapt. Als je hem aan Thadius geeft, kan hij met wat geluk zijn waarzeggende magie gebruiken om Sharpbeak te vinden.$B$BSucces, $N. Je vindt Thadius in de Blasted Lands, in de magiërstoren van Nethergarde Keep.",
  o = "Breng Sharpbeak's Feather naar Thadius Grimshade in de Blasted Lands.",
  p = "$N, kom je met een geschenk?",
  c = "Ah, ja. Deze veer is van een prachtige griffioen. Een griffioen voor wie grote dingen zijn weggelegd... als hij zonder schade volwassen kan worden.$B$BWil je hem vinden? Luister dan goed, dappere $c...",
  g = { {"veer", "feather"}, {"waarzegger", "diviner, fortune-teller"}, {"duisterdere", "darker (duister)"}, {"kennis", "knowledge"}, {"griffioenjong", "gryphon child, young gryphon"}, {"waarzeggende", "divining (waarzeggen)"}, {"magiërstoren", "mage tower"}, {"geschenk", "gift"}, {"zijn weggelegd", "are destined (weggelegd zijn voor)"}, {"volwassen", "adult, grown-up"}, {"dappere", "brave (dapper)"} },
},

[2992] = { en = "The Divination", tier = 4,
  t = "De waarzegging",
  d = "Geef me ruimte terwijl ik een waarzeggingsritueel uitvoer. Ik zal de verbinding vinden tussen de veer die je me bracht en de eigenaar ervan. Die verbinding volg ik dan naar Sharpbeak zelf.$B$BTenminste... als alles volgens plan gaat. Als dat niet zo is, dan... kun je beter je ogen dichtdoen.",
  o = "Wacht tot Grimshade het waarzeggingsritueel uitvoert.",
  c = "Het ritueel is gelukt. Ik heb Sharpbeak gezien en kan je vertellen hoe je hem vindt.",
  e = "Wacht tot Grimshade klaar is",
  g = { {"waarzegging", "divination"}, {"ruimte", "room, space"}, {"waarzeggingsritueel", "ritual of divination"}, {"uitvoer", "perform (uitvoeren)"}, {"verbinding", "connection"}, {"eigenaar", "owner"}, {"tenminste", "that is, at least"}, {"volgens plan", "according to plan"}, {"dichtdoen", "to close"} },
