[2993] = { en = "Return to the Hinterlands", tier = 4,
  t = "Terug naar de Hinterlands",
  d = "Sharpbeak zit in een kooi, hoog op een klif boven op Jintha'Alor in de Hinterlands. De sleutel van deze kooi is in handen van de hogepriesteres van de Vilebranch-trollen, Vile Priestess Hexx.$B$BZo. Ik heb mijn deel gedaan. Ik wens je geluk bij je zoektocht, $N.",
  o = "Spreek met Gryphon Master Talonaxe.",
  c = "Heb je met Grimshade gesproken? Wat zei hij?$B$B...Wat? Hebben de Vilebranch-trollen Sharpbeak? Dat is ondraaglijk! We moeten een troepenmacht verzamelen om hem terug te halen!",
  g = { {"kooi", "cage"}, {"klif", "cliff"}, {"in handen van", "in the hands of, possessed by"}, {"hogepriesteres", "high priestess"}, {"deel", "part"}, {"zoektocht", "quest, search"}, {"ondraaglijk", "unbearable"}, {"troepenmacht", "(military) force"}, {"verzamelen", "to gather, to organize"} },
