[4451] = { en = "The Key to Freedom", tier = 4,
  t = "De sleutel naar vrijheid",
  d = "Het kleine koperen sleuteltje ziet er simpel uit. Het enige wat opvalt, zijn een paar woorden die in de kop zijn gekrast:$B$B\"Dark Iron Outhouse - Niet namaken.\"$B$BJe hebt geen idee wat het betekent of waar het naartoe leidt.",
  o = "Doorzoek Searing Gorge en vind een gebruik voor de Grimesilt Outhouse Key die je hebt gevonden.",
  p = "*kuch*$B$BWie is daar? Zie je niet dat ik bezig ben?",
  c = "Nou ja, zeg! Hoe is het in vredesnaam mogelijk!? Je hebt de sleutel gevonden! Ik wist dat die vervloekte Dark Irons hem verstopten nadat ze me hier hadden opgesloten! Heel erg bedankt, $N. Je bent de beste! Draai nu gewoon de sleutel om en laat de ouwe Locheed hieruit!",
  g = { {"vrijheid", "freedom"}, {"koperen", "brass, copper (koper)"}, {"opvalt", "stands out (opvallen)"}, {"kop", "head (of a key)"}, {"gekrast", "scratched (krassen)"}, {"namaken", "to copy, to duplicate"}, {"kuch", "cough"}, {"nou ja, zeg", "well, I'll be"}, {"in vredesnaam", "in heaven's name, in tarnation"}, {"vervloekte", "blasted, cursed (vervloekt)"}, {"verstopten", "hid (verstoppen)"}, {"opgesloten", "locked up (opsluiten)"}, {"ouwe", "old (informal: oude)"} },
},

[77] = { en = "A Sticky Situation", tier = 4,
  t = "Een plakkerige situatie",
  d = "Ik bezit het originele verpakkingsmateriaal voor de ripple die Dran Droffers zoekt. Ik help je de ripple in te pakken voor Maltons botte vader... in ruil voor twee extra flessen van die ripple. Ze liggen in kratten in de verlaten Horde-basis bij Skulk Rock.$B$BHet wordt een zware taak, namelijk: smerige slijmmonsters en blubbermonsters plakken vast aan de ruïnes. Volgens de geruchten worden ze geleid door een soort meesterblubbermonster. Hoe dan ook, haal de ripple en kom hier terug om hem te laten inpakken.",
  o = "Haal 10 flessen Hinterlands Honey Ripple uit de kratten rond de verlaten Horde-basis bij Skulk Rock.",
  p = "Ik neem aan dat je naar ons kamp komt om de flessen ripple te brengen die onmisbaar zijn voor deze taak, nietwaar?",
  c = "Keurig uitgevoerd, $n. Ik ben blij dat je zo vooruitziend was om de delicate ripple niet te kneuzen. Er is niets ergers dan het aroma van ripple die onnodig door elkaar is geschud.$B$BHet duurt even voordat de magie over deze kostbare lading is uitgesproken. Eigenlijk komt er geen magie aan te pas; ik heb alleen wat lege verpakkingen van Hinterlands Honey Ripple. Met onze list worden deze flessen een alcoholische schat aller tijden.$B$BVoorwaarts - voor geweldige drank!",
  g = { {"plakkerige", "sticky (plakkerig)"}, {"bezit", "possess (bezitten)"}, {"verpakkingsmateriaal", "packaging materials"}, {"botte", "blunt, abrasive (bot)"}, {"in ruil voor", "in exchange for"}, {"kratten", "crates (krat)"}, {"smerige", "foul, filthy (smerig)"}, {"blubbermonsters", "oozes (blubbermonster)"}, {"onmisbaar", "integral, indispensable"}, {"vooruitziend", "far-sighted, with foresight"}, {"kneuzen", "to bruise"}, {"aroma", "bouquet, aroma"}, {"lading", "cargo"}, {"list", "trick, chicanery"}, {"aller tijden", "of all time, of the ages"} },
},

[485] = { en = "Find OOX-09/HL!", tier = 4,
  t = "Zoek OOX-09/HL!",
  d = "Je hebt een vreemd, eivormig apparaat van metaal gevonden. Als je aan een van de knoppen draait, komt het ei tot leven. Het gaat open en wordt een soort robot van de gnomen! Uit het robotei klinkt krakend een stem.$B$B\"Ik heet Oglethorpe Obnoticus, en mijn terugkeerrobot is neergestort! Ik beloon je als je hem terugvindt. Breng dit baken alsjeblieft naar de robot!\"$B$B\"Ik heb nu de coördinaten van de robot voor je berekend: hij is neergestort bij de bron van de rivier bij Skulk Rock!\"",
  o = "Breng het noodbaken naar Oglethorpe's terugkeerrobot bij de bron van de rivier in de Hinterlands, bij Skulk Rock.",
  p = "Je lijkt het wrak te hebben gevonden van... een robotkip? De stem in het ei komt krakend weer tot leven:$B$B\"Ja, uitstekend werk! Dit is inderdaad mijn terugkeerrobot. Maar volgens mijn sensoren heeft hij een startduwtje nodig voordat hij terug kan vliegen naar Booty Bay voor reparaties. Leg het baken maar in het voertuig - het baken doet de rest!\"",
  c = "Je legt het ei... noodbaken... in de kip... terugkeerrobot.$B$BUit de robot klinkt gezoem en gesnor terwijl hij moeite doet om op te staan. Als de robot tot leven komt, hoor je Oglethorpe's stem opnieuw, maar nu uit de robot:$B$B\"OOX-09/HL werkt in elk geval, maar hij heeft grote reparaties nodig! Hij is veel te zwaar voor jou om te dragen... maar ik denk dat ik een idee heb. Wil je nog wat langer op hem passen?\"",
  g = { {"eivormig", "egg-shaped"}, {"knoppen", "knobs (knop)"}, {"krakend", "crackling (kraken)"}, {"terugkeerrobot", "homing robot"}, {"neergestort", "crashed (neerstorten)"}, {"baken", "beacon"}, {"berekend", "computed, calculated (berekenen)"}, {"bron", "head, source (of a river)"}, {"noodbaken", "distress beacon"}, {"wrak", "wreckage"}, {"startduwtje", "jump start"}, {"voertuig", "vehicle, rover"}, {"gezoem en gesnor", "hums and whirs"}, {"moeite doet", "struggles (moeite doen)"}, {"op hem passen", "to watch over him (passen op)"} },
},

[836] = { en = "Rescue OOX-09/HL!", tier = 4,
  t = "Red OOX-09/HL!",
  d = "De stem van de gnoom klinkt weer krakend uit de robot:$B$B\"Ik moet OOX-09/HL naar een open, veilige plek brengen, zodat hij aan een lange opstijgprocedure kan beginnen. Hij heeft een ingebouwde onzichtbaarheidsfunctie, maar ik heb aan mijn kant tijd nodig om die weer werkend te krijgen. Begeleid de robot van zijn huidige plek naar, zeg maar, de kust voorbij Overlook Cliff! Dat is een perfecte plek, en het duurt lang genoeg, om alles weer online te krijgen!\"$B$B\"Begeleid hem veilig naar de kust en kom dan met me praten in Booty Bay! Oglethorpe Obnoticus - over en uit!\"",
  o = "Begeleid OOX-09/HL naar de kust voorbij Overlook Cliff en meld je daarna bij Oglethorpe Obnoticus in Booty Bay.",
  c = "O, JIJ bent de grote redder van OOX-09/HL! Ik kan niet eens beginnen te zeggen hoe dankbaar ik ben voor je hulp! Mijn reeks terugkeerrobots moet nog verder ontwikkeld worden, maar door jouw redding heb ik talloze uren extra herbouwen bespaard, en ook veel goudstukken aan productiekosten!$b$bKies alsjeblieft een van deze voorwerpen die ik heb. Nogmaals bedankt voor je gulle hulp, $N. Mijn robots en ik staan bij je in het krijt!",
  e = "Begeleid OOX-09/HL naar de kust voorbij Overlook Cliff",
  g = { {"opstijgprocedure", "take-off procedure"}, {"ingebouwde", "built-in (ingebouwd)"}, {"onzichtbaarheidsfunctie", "cloaking (function)"}, {"begeleid", "escort (begeleiden)"}, {"huidige", "current (huidig)"}, {"kust", "shore, coast"}, {"over en uit", "over and out"}, {"redder", "saviour"}, {"reeks", "series"}, {"ontwikkeld", "developed (ontwikkelen)"}, {"talloze", "countless (talloos)"}, {"bespaard", "saved (besparen)"}, {"productiekosten", "manufacture costs"}, {"gulle", "generous (gul)"}, {"bij je in het krijt staan", "to be in your debt"} },
},

[2877] = { en = "Skulk Rock Clean-up", tier = 4,
  t = "Skulk Rock opruimen",
  d = "Wij Wildhammers denken meer aan het verleden dan onze broeders in Ironforge. Als je hier vrienden wilt maken, moet je voor ons je handen vuil maken!$B$BDe Horde heeft hun posities in de Hinterlands rond Skulk Rock verlaten. Nu wemelt het daar van smerige slijkmonsters en blubbermonsters. We hebben plannen met dat gebied, maar eerst hebben we een schoonmaakploeg nodig die de weg voor ons vrijmaakt.$B$BEn daar kom jij in beeld, zonnetje! Ga daarheen, maak tien Green Sludges en tien Jade Oozes af, en meld je daarna weer bij mij. Vooruit!",
  o = "Dood 10 Green Sludges en 10 Jade Oozes en meld je daarna bij Fraggar Thundermantle in Aerie Peak.",
  p = "Probeer niet over deze missie te onderhandelen, $r! Als de goden die blubbermonsters dood hadden gewild, hadden ze dat nu toch al met een wonder gedaan?!",
  c = "Moet je jou nou zien, je helpt de Wildhammers! Je bent een $c van actie, en actie is wat we hier respecteren.$B$BJe kleine schoonmaakmissie is veel belangrijker dan je misschien denkt. Nu er mensen zijn die de blubbermonsters en slijkmonsters uitdunnen, kunnen we onze invloed snel uitbreiden. Hier - neem iets kleins, naast de nieuwe vrienden die je hier in Aerie Peak hebt gemaakt!",
  g = { {"opruimen", "to clean up"}, {"broeders", "brothers (broeder)"}, {"je handen vuil maken", "to get your hands dirty"}, {"wemelt", "teems, is overrun (wemelen)"}, {"slijkmonsters", "sludges (slijkmonster)"}, {"schoonmaakploeg", "clean-up crew"}, {"vrijmaakt", "clears (vrijmaken)"}, {"in beeld komen", "to come in, to enter the picture"}, {"zonnetje", "sunshine"}, {"onderhandelen", "to negotiate"}, {"wonder", "miracle"}, {"uitdunnen", "to thin out"}, {"invloed", "influence"}, {"uitbreiden", "to extend, to expand"} },
},

[2989] = { en = "The Altar of Zul", tier = 4,
  t = "Het Altar of Zul",
  d = "Sharpbeak was niet bij de Witherbark-trollen. Misschien hebben de Vilebranch-trollen hem meegenomen. Ga naar het Altar of Zul aan de westrand van het Vilebranch-gebied en zoek het griffioenjong.",
  o = "Kijk boven op het Altar of Zul en keer dan terug naar Gryphon Master Talonaxe.",
  p = "Schiet op, $N! Als de Vilebranch-trollen Sharpbeak hebben, wie weet wat ze dan met hem doen!",
  c = "Was Sharpbeak er niet? Dat is slecht nieuws, maar ook goed nieuws...$B$BHet is goed dat hij niet bij het Altar of Zul was, want de Vilebranch-trollen staan erom bekend dat ze offers brengen.$B$BIk dank je voor al je hulp, maar ik vrees dat er een nog grotere taak wacht.",
  e = "Doorzoek het Altar of Zul",
  g = { {"meegenomen", "taken (away) (meenemen)"}, {"westrand", "western edge"}, {"gebied", "territory, area"}, {"griffioenjong", "gryphon child, young gryphon"}, {"schiet op", "hurry up (opschieten)"}, {"staan erom bekend", "are known for it (bekendstaan)"}, {"offers brengen", "to perform sacrifices"}, {"vrees", "fear (vrezen)"}, {"doorzoek", "search (doorzoeken)"} },
},

[3181] = { en = "The Horn of the Beast", tier = 4,
  t = "De hoorn van het beest",
  d = "De gigantische hoorn zit vol krassen en barsten. Er zit een vreemd metalen voorwerp vast in het ruwe oppervlak.$B$BAls je beter kijkt, zie je dat het metaal eigenlijk een gebroken bijlkop is. In het metaal zijn deze woorden gegraveerd:$B$BEigendom van Mountaineer Pebblebitty.$B$BAls je de gebroken bijlkop probeert los te maken, valt hij in een miljoen stukjes.$B$BOeps!",
  o = "Breng Margol's Gigantic Horn naar Mountaineer Pebblebitty.$b",
  p = "Nee, ik doe de poort niet open.",
  c = "Wat heb je daar? Namaak, natuurlijk!$B$BIk heb oog in oog gestaan met Margol, en ik weet zeker dat haar hoorn minstens acht keer groter is dan die in jouw handen, $N. Die heb je vast van een stormsnout in de Barrens. Nee $g meneer:mevrouw;, Pebblebitty laat zich niet foppen!",
  g = { {"hoorn", "horn"}, {"krassen", "scratches (kras)"}, {"barsten", "cracks (barst)"}, {"ruwe", "rough (ruw)"}, {"oppervlak", "surface"}, {"bijlkop", "axe head"}, {"gegraveerd", "etched, engraved (graveren)"}, {"eigendom", "property"}, {"los te maken", "to dislodge, to loosen (losmaken)"}, {"namaak", "fake, imitation"}, {"oog in oog", "face to face"}, {"minstens", "at least"}, {"foppen", "to fool"} },
},

