[3368] = { en = "Suntara Stones", tier = 4,
  t = "De Suntara-stenen",
  d = "Broeder,$B$BAls je deze brief leest, ben ik er niet meer. Ik weet niet hoe hij bij jou is gekomen, maar bedank en beloon degenen die dat gedaan hebben.$B$BOver de stenen: ze bestaan, en de Dark Irons hebben ze in hun bezit. Hun leider, Lathoric the Black, gebruikt de kracht van de stenen om mijn opgravingsteam tot slaaf te maken. Ze zijn naar de Cauldron gebracht. Hun geest is verdraaid, en ze werken dag en nacht om iets af te maken dat Obsidion heet.$B$BHelp hen, broeder. Het is de laatste wens van een dode man.$B$B-Dorius$b",
  o = "Breng de Singed Letter naar Thorius in Ironforge. Hij is in de Hall of Explorers.",
  p = "<Thorius snikt.>",
  c = "<Thorius veegt zijn gezicht droog.>$B$BIn de naam van het Licht: hij krijgt zijn wens. Dat zweer ik.",
  g = { {"broeder", "brother"}, {"degenen", "the ones, those (degene)"}, {"in hun bezit", "in their possession"}, {"opgravingsteam", "excavation team"}, {"tot slaaf maken", "to enslave"}, {"geest", "mind"}, {"verdraaid", "twisted (verdraaien)"}, {"wens", "wish"}, {"snikt", "sobs (snikken)"}, {"veegt", "wipes (vegen)"}, {"zweer", "vow, swear (zweren)"} },
},

