[3442] = { en = "The Flawless Flame", tier = 4,
  t = "De smetteloze vlam",
  d = "Je hebt de juiste beslissing genomen, $N.$B$BWe moeten toeslaan waar we de meeste schade aanrichten: bij de vier wachttorens.$B$BAls de vier torens in brand staan, kunnen we een aanval beginnen voordat ze tijd hebben om te reageren.$B$BJe hebt het juiste gereedschap nodig om de torens in brand te steken. Voor dat gereedschap zijn materialen nodig.$B$BBreng me vier Hearts of Flame en vier Golem Oil, dan maak ik de fakkel van de smetteloze vlam.$B$BDe golems en elementalen in dit land moeten je eerste doelwit zijn.",
  o = "Verzamel 4 Hearts of Flame en 4 bollen Golem Oil en breng de spullen naar Kalaran Windblade.",
  p = "Heb je de materialen verzameld?",
  c = "Goed gedaan, $N. We zijn bijna klaar.",
  g = { {"smetteloze", "flawless (smetteloos)"}, {"beslissing", "decision"}, {"toeslaan", "to strike"}, {"schade aanrichten", "to do damage"}, {"wachttorens", "sentry towers (wachttoren)"}, {"in brand steken", "to set ablaze, to set on fire"}, {"gereedschap", "tool(s)"}, {"fakkel", "torch"}, {"elementalen", "elementals (elementaal)"}, {"doelwit", "target"}, {"bollen", "globes (bol)"} },
},

[3443] = { en = "Forging the Shaft", tier = 4,
  t = "De schacht smeden",
  d = "Om de smetteloze vlam vast te houden, hebben we een schacht en een omhulsel nodig. Eerst moet je een geschikte schacht vinden.$B$BDe Dark Iron-opzichters en slavendrijvers van de Cauldron gebruiken wapens van betoverd thorium, een extreem sterke legering. Als je me acht dolken met thoriumplaten brengt, kan ik de legering afbreken en er een nieuwe schacht van smeden.$b",
  o = "Breng 8 Thorium Plated Daggers naar Kalaran Windblade.",
  p = "Acht, $N. Ik heb er acht nodig!",
  c = "Je bent een uitzonderlijke arbeider, $N. Heb je ooit aan een ander beroep gedacht? Misschien detective? Rommelverzamelaar? O, ik weet het: een van die rare gnomen die met hun metaaldetectors over de stranden van Azeroth kruipen, op zoek naar verloren schatten. Ja, dat zou een ideale baan voor je zijn.",
  g = { {"schacht", "shaft"}, {"smeden", "to forge"}, {"omhulsel", "casing"}, {"geschikte", "suitable (geschikt)"}, {"opzichters", "taskmasters, overseers (opzichter)"}, {"slavendrijvers", "slavers (slavendrijver)"}, {"betoverd", "enchanted (betoveren)"}, {"legering", "alloy"}, {"dolken", "daggers (dolk)"}, {"uitzonderlijke", "exceptional (uitzonderlijk)"}, {"arbeider", "labourer, worker"}, {"beroep", "vocation, profession"}, {"rommelverzamelaar", "junk collector"}, {"kruipen", "to crawl"} },
},

[7728] = { en = "STOLEN: Smithing Tuyere and Lookout's Spyglass", tier = 4,
  t = "GESTOLEN: Smithing Tuyere en Lookout's Spyglass",
  d = "De volgende voorwerpen zijn gestolen:$B$B*Eén Dark Iron Tuyere.$B$B*Eén Lookout's Spyglass.$B$BEr is een beloning voor wie deze gestolen voorwerpen vindt en terugbrengt.$B$BDe Thorium Brotherhood weet zeker dat deze voorwerpen gestolen zijn door gewetenloze, jaloerse Dark Iron-dwergen die in Searing Gorge wonen.$B$BDe verrekijker in kwestie was een uitstekend hulpmiddel voor de uitkijkposten, en de blaaspijp was een onvervangbaar smidsgereedschap.$B$BAls je de vermiste voorwerpen vindt, breng ze dan terug naar Scrange.",
  o = "Vind de Smithing Tuyere en de Lookout's Spyglass en breng ze terug naar Taskmaster Scrange in Searing Gorge.$B$BDit is het enige wat je over deze voorwerpen weet: ze zijn zeker gestolen door Dark Iron-dwergen. De Smithing Tuyere is een smidsgereedschap dat smeden gebruiken, en de Lookout's Spyglass is een onmisbaar hulpmiddel voor uitkijkposten om de omgeving in de gaten te houden.",
  p = "Als je hier bent voor de beloning, moet je me de gestolen spullen geven.",
  c = "Fantastisch werk! Nu je beloning.",
  g = { {"gestolen", "stolen (stelen)"}, {"beloning", "reward"}, {"gewetenloze", "unscrupulous (gewetenloos)"}, {"jaloerse", "jealous (jaloers)"}, {"verrekijker", "spyglass, binoculars"}, {"in kwestie", "in question"}, {"hulpmiddel", "tool, aid"}, {"uitkijkposten", "lookouts (uitkijkpost)"}, {"blaaspijp", "tuyere (a blacksmith's air pipe)"}, {"onvervangbaar", "irreplaceable"}, {"smidsgereedschap", "smithing tool"}, {"vermiste", "missing (vermist)"}, {"smeden", "blacksmiths (smid)"}, {"in de gaten houden", "to keep an eye on, to monitor"} },
},

[7729] = { en = "JOB OPPORTUNITY: Culling the Competition", tier = 4,
  t = "VACATURE: De concurrentie uitdunnen",
  d = "Taskmaster Scrange zoekt een paar goede mannen en vrouwen die willen helpen om 'de concurrentie uit te dunnen' in Searing Gorge.$B$BHeb je interesse in deze functie? Trek dan Searing Gorge in en slacht elke Dark Iron Taskmaster en Dark Iron Slaver af die je ziet.$B$BKeer terug naar Taskmaster Scrange als je kleren bebloed genoeg zijn.$B$BJe weet wel wanneer ze bebloed genoeg zijn, dus vraag er niet naar.",
  o = "Dood 15 Dark Iron Taskmasters en 15 Dark Iron Slavers. Keer terug naar Taskmaster Scrange in Searing Gorge als je deze taak hebt volbracht.",
  p = "We moeten je wegen met en zonder kleren om het zeker te weten.",
  c = "15,9 pond! Dat is misschien een nieuw record voor bloed- en ingewandengewicht op kleding! Gefeliciteerd, $c!",
  g = { {"vacature", "job opportunity, vacancy"}, {"concurrentie", "competition"}, {"uitdunnen", "to cull, to thin out"}, {"functie", "position, job"}, {"trek ... in", "venture out into (intrekken)"}, {"slacht ... af", "slaughter (afslachten)"}, {"bebloed", "bloody, bloodstained"}, {"volbracht", "accomplished (volbrengen)"}, {"wegen", "to weigh"}, {"pond", "pound (weight)"}, {"ingewanden", "guts, entrails"} },
},

[7723] = { en = "Curse These Fat Fingers", tier = 4,
  t = "Vervloekt zijn deze dikke vingers",
  d = "Helaas kan ik niet meer zo hard uitdelen als vroeger, door dit probleem met mijn dikke vingers. Zie je, het klimaat hier en de lage luchtdruk samen laten mijn vingers opzwellen. Ze zijn net gigantische Thelsamar Blood Sausages, echt waar...$B$BJij moet mijn zaken maar afhandelen, en zo.$B$BEerste punt op mijn agenda: de heavy war golems van de Gorge bont en blauw slaan. Aan de slag.",
  o = "Hansel Heavyhands wil dat je 20 Heavy War Golems doodt.$B$BDe Heavy War Golems lopen rond in de gebieden rond de Cauldron in Searing Gorge. Keer terug naar Hansel in Searing Gorge als je er genoeg hebt gedood.",
  p = "Heb je ze in elkaar geslagen?",
  c = "Je bent een goeie $g jongen:meid;, echt waar. Ik heb een klein cadeautje voor je, voor de moeite.",
  g = { {"vervloekt", "cursed"}, {"helaas", "unfortunately"}, {"uitdelen", "to dish out (blows)"}, {"klimaat", "climate"}, {"luchtdruk", "air pressure"}, {"opzwellen", "to swell, to expand"}, {"zaken afhandelen", "to carry out business"}, {"bont en blauw slaan", "to beat black and blue"}, {"aan de slag", "get cracking, get to work"}, {"in elkaar geslagen", "beaten up (in elkaar slaan)"}, {"goeie", "good (informal: goede)"}, {"voor de moeite", "for your troubles"} },
},

[7724] = { en = "Fiery Menace!", tier = 4,
  t = "Vurige dreiging!",
  d = "Wat denk je: elke keer als de ouwe Hansel even wil ontspannen en over zijn leven wil nadenken, geven de hogere machten hem weer een nieuwe klus.$B$BIk moet nadenken, kom op! Snap je wat ik bedoel? Kom. Op.$B$BNou, die greater lava spiders hier maken een of ander soort herrie. Oilfist zegt dat ze vuur schieten uit hun... ehm, ja, nou ja, hoe dan ook, zulke dingen maken de kinderen van streek.$B$BIk denk dat we ze moeten doden. Of eigenlijk: jij moet ze doden.",
  o = "Hansel Heavyhands wil dat je 20 Greater Lava Spiders doodt in Searing Gorge. Je vindt Greater Lava Spiders op de plateaus en in de lavapoelen van Searing Gorge.$B$BKeer terug naar Hansel Heavyhands in Searing Gorge als je genoeg Greater Lava Spiders hebt gedood.",
  p = "Had hij gelijk? Komt het uit hun achterwerk?",
  c = "<Hansel niest.>$B$BIk denk dat ik verkouden word. Verdorie, wat een ijskoud klimaat!",
  g = { {"vurige", "fiery (vurig)"}, {"dreiging", "menace, threat"}, {"ontspannen", "to relax"}, {"nadenken", "to reflect, to think"}, {"de hogere machten", "the powers that be"}, {"herrie", "ruckus, racket"}, {"van streek maken", "to upset"}, {"lavapoelen", "lava pools (lavapoel)"}, {"achterwerk", "rump, backside"}, {"niest", "sneezes (niezen)"}, {"verkouden", "having a cold"}, {"verdorie", "damn, darn"}, {"ijskoud", "ice-cold, frigid"} },
},

[7727] = { en = "Incendosaurs? Whateverosaur is More Like It", tier = 4,
  t = "Incendosaurs? Watdanookosaurus, zul je bedoelen",
  d = "Knobbels, $g jongen:meid;. Mijn knobbels hebben knobbels. Hoe moet ik nou iets doden met mijn voeten in zo'n toestand? Daarom ga jij helpen.$B$BScrange en Burninate hebben me opgedragen die dingen te doden, zodat ze wat onderzoeksteams naar de lavapoelen van de Slag Pit kunnen sturen om op verkenning te gaan. Daar beneden zouden incendosaurs of zoiets onzinnigs allerlei problemen veroorzaken. Ga nu maar, en kom niet terug tot de incendosaurs zijn uitgestorven.",
  o = "Hansel Heavyhands wil dat je 20 Incendosaurs doodt.$B$BJe vindt Incendosaurs in de lavapoelen in de Slag Pit. De Slag Pit ligt in de Cauldron van Searing Gorge.$B$BKeer terug naar Hansel Heavyhands in Searing Gorge als je genoeg Incendosaurs hebt gedood.",
  p = "<Hansel wrijft druk over zijn knobbels.>$B$BSta daar niet zo, pak wat olie en een luffa en begin die knobbels te schrobben.$B$BHeb je geen luffa? Nou dan! Misschien wordt het tijd dat ik je op pad stuur om een luffa te zoeken?$B$BHé, waar ga je heen?",
  c = "O, mijn arme pijnlijke voeten.$B$BIk dacht al, omdat je geen luffa had...",
  g = { {"knobbels", "bunions (knobbel)"}, {"toestand", "state, disarray"}, {"opgedragen", "tasked (opdragen)"}, {"onderzoeksteams", "expeditionary teams (onderzoeksteam)"}, {"op verkenning gaan", "to go exploring"}, {"onzinnigs", "nonsense (onzinnig)"}, {"veroorzaken", "to cause"}, {"uitgestorven", "extinct (uitsterven)"}, {"wrijft", "rubs (wrijven)"}, {"luffa", "loofah"}, {"schrobben", "to scrub"}, {"op pad sturen", "to send out"}, {"pijnlijke", "aching, painful (pijnlijk)"} },
},

[3377] = { en = "Prayer to Elune", tier = 4,
  t = "Gebed tot Elune",
  d = "Wil je me helpen, sterveling? Hoor mijn verhaal.",
  o = "Luister naar het verhaal van Zamael.",
  p = "Laat me mijn verhaal afmaken.",
  c = "Ik heb mijn lot hier in deze kooi aanvaard, maar het gebed moet gevonden worden.$b",
  e = "Zamaels verhaal",
  g = { {"gebed", "prayer"}, {"sterveling", "mortal"}, {"lot", "fate"}, {"kooi", "cage"}, {"aanvaard", "accepted (aanvaarden)"} },
},

[3378] = { en = "Prayer to Elune", tier = 4,
  t = "Gebed tot Elune",
  d = "Wil je me helpen, sterveling? Wil je het gebed tot Elune vinden?$B$BZoals ik al zei, werd het gebed in een gouden tablet gegraveerd. Een van deze schurken die afgodsbeelden aanbidden, moet het bij zich hebben.$B$BAls je mijn gebed terugvindt, breng het dan naar Astarii Starseeker in Darnassus. Het maakt weinig uit dat mijn geloof weer is opgevlamd na de talloze kwade daden die ik tegen deze wereld en haar bewoners heb begaan, maar mijn gebed moet gehoord worden. Vergeving is het laatste wat ik verwacht.",
  o = "Vind de Prayer to Elune en breng die naar Astarii Starseeker in Darnassus.$b",
  p = "Wat brengt je naar de Temple of the Moon, $N?",
  c = "Elune glimlacht vanavond naar je, $N. Je hebt een verloren ziel aan haar teruggegeven. Neem dit alsjeblieft aan als teken van onze dankbaarheid.",
  g = { {"gegraveerd", "etched, engraved (graveren)"}, {"schurken", "scoundrels, villains (schurk)"}, {"afgodsbeelden", "idols (afgodsbeeld)"}, {"aanbidden", "to worship"}, {"geloof", "faith"}, {"opgevlamd", "rekindled, flared up (opvlammen)"}, {"kwade daden", "malevolent actions, evil deeds"}, {"bewoners", "inhabitants (bewoner)"}, {"begaan", "committed (begaan)"}, {"vergeving", "absolution, forgiveness"}, {"ziel", "soul"}, {"dankbaarheid", "gratitude"} },
},

[3452] = { en = "The Flame's Casing", tier = 4,
  t = "Het omhulsel van de vlam",
  d = "We hebben nog één laatste onderdeel nodig om de fakkel te maken.$B$BIn de bergen in het noordwesten vind je een groot kamp van de Twilight's Hammer. Men zegt dat ze symbolen en afgodsbeelden bij zich dragen die hun god eren. Die symbolen en beelden kunnen genoeg betovering bevatten om een magisch omhulsel te vormen. Breng me één Symbol of Ragnaros, dan probeer ik de magie uit het voorwerp te halen om het omhulsel te maken.",
  o = "Vind een Symbol of Ragnaros en breng het naar Kalaran Windblade.",
  p = "Zonder een geschikte bron van arcane energie kan de fakkel van vergelding niet worden afgemaakt.",
  c = "Het symbool straalt smerige magie uit; perfect voor onze taak.",
  g = { {"omhulsel", "casing"}, {"onderdeel", "piece, part"}, {"afgodsbeelden", "idols (afgodsbeeld)"}, {"eren", "to honour, to pay homage to"}, {"betovering", "enchantment"}, {"bevatten", "to contain"}, {"geschikte", "suitable (geschikt)"}, {"arcane", "arcane (arcaan)"}, {"vergelding", "retribution"}, {"straalt ... uit", "radiates (uitstralen)"} },
},

