  o = "Wacht tot Kalaran Windblade de Torch of Retribution heeft voltooid.$b",
  p = "Onderbreek het kanaliseren niet.",
  c = "Er is nog één laatste taak die je moet voltooien.$b",
  e = "De fakkel maken",
  g = { {"onderdelen", "pieces, parts (onderdeel)"}, {"samen te voegen", "to combine (samenvoegen)"}, {"betoveringen", "enchantments (betovering)"}, {"aan te brengen", "to apply (aanbrengen)"}, {"voltooid", "completed (voltooien)"}, {"onderbreek", "interrupt (onderbreken)"}, {"kanaliseren", "channeling"} },
},

