[4787] = { en = "The Ancient Egg", tier = 4,
  t = "Het oeroude ei",
  d = "De Prophecy of Mosh'aru spreekt over een oeroud ei. Het is een overblijfsel uit een tijd waarin trollen over grote rijken heersten, en het kan de essentie van Hakkar vasthouden. Misschien is het de enige manier om onze wereld te beschermen tegen zijn kwaad.$B$BBreng me het oeroude ei, $N. Men zegt dat het diep in Jintha'Alor in de Hinterlands verborgen ligt, in een grot achter het amfitheater boven in de stad.",
  o = "Breng het Ancient Egg naar Yeh'kinya in Tanaris.",
  p = "Heb je het oeroude ei? Ik voel grote krachten in beweging komen, en ik vrees dat de tijd begint te dringen.",
  c = "Ah, je hebt het ei! Ik buig voor je, $N. Je kracht en moed zullen nog lang herinnerd worden.",
  g = { {"oeroude", "ancient (oeroud)"}, {"overblijfsel", "relic, remnant"}, {"rijken", "empires (rijk)"}, {"heersten", "ruled (heersen)"}, {"essentie", "essence"}, {"kwaad", "evil"}, {"verborgen", "hidden (verbergen)"}, {"amfitheater", "amphitheater"}, {"in beweging komen", "to start stirring, to start moving"}, {"de tijd begint te dringen", "time grows short"}, {"buig", "bow (buigen)"}, {"moed", "bravery, courage"}, {"herinnerd", "remembered (herinneren)"} },
},

[2994] = { en = "Saving Sharpbeak", tier = 4,
  t = "Red Sharpbeak",
  d = "We moeten Sharpbeak redden!$B$BVecht je een weg naar de top van Jintha'Alor, in het hart van het Vilebranch-gebied. Haal de sleutel van Sharpbeaks kooi bij de gemene Priestess Hexx, en vind en red Sharpbeak!",
  o = "Vecht je een weg naar de top van Jintha'Alor, dood Vile Priestess Hexx voor de sleutel van Sharpbeaks kooi, en red Sharpbeak.",
  p = "Red Sharpbeak!",
  c = "Swiftwind en Keenclaw zijn net teruggekomen met hun jong, en ze doen druk om hem heen als nieuwe ouders. Als ik ze weer samen zie, krijgt zelfs deze oude dwerg vochtige ogen...$B$BWe kunnen je nooit genoeg terugbetalen voor wat je gedaan hebt, $N. De griffioenen van Aerie Peak en hun ruiters zullen je naam nog heel lang bezingen.",
  o2 = "Open Sharpbeak's Cage",
  g = { {"vecht je een weg", "fight your way (vechten)"}, {"gemene", "vile, mean (gemeen)"}, {"jong", "young (of an animal), child"}, {"druk doen om", "to fuss over"}, {"vochtige", "moist, teary (vochtig)"}, {"terugbetalen", "to repay"}, {"ruiters", "riders (ruiter)"}, {"bezingen", "to sing (of), to praise in song"} },
},

[8925] = { en = "A Portable Power Source", tier = 4,
  t = "Een draagbare energiebron",
  d = "Nu moeten we een stabiele, draagbare energiebron vinden om het ectoplasma actief te houden. Ik heb geruchten gehoord over een machtige elementaal: Magma Lord Bokk. Zijn hart is een krachtige magmakern, een eindeloze bron van hitte!$B$BMen zegt dat hij in de Burning Steppes te vinden is, ten zuiden van Blackrock Mountain. Breng de magmakern naar mij, dan hebben we genoeg stroom voor de extradimensionale spokenonthuller!",
  o = "Zoek Magma Lord Bokk in de Burning Steppes, haal zijn Magma Core en breng die naar Mux Manascrambler in Gadgetzan.",
  p = "Heb je de Magma Lord gevonden, $N?",
  c = "Het is je gelukt! Dit geeft zeker genoeg energie om de extradimensionale spokenonthuller aan te zetten!",
  g = { {"draagbare", "portable (draagbaar)"}, {"energiebron", "energy source"}, {"stabiele", "stable (stabiel)"}, {"geruchten", "rumours (gerucht)"}, {"elementaal", "elemental (a being of fire, earth, water or air)"}, {"magmakern", "magma core"}, {"eindeloze", "endless (eindeloos)"}, {"hitte", "heat"}, {"stroom", "power, electricity; juice"}, {"extradimensionale", "extra-dimensional"}, {"spokenonthuller", "ghost revealer"} },
},

[8928] = { en = "A Shifty Merchant", tier = 4,
  t = "Een louche handelaar",
  d = "De kern geeft ons genoeg stroom voor ons apparaat. Nu moeten we alleen nog een staaf bouwen die die energie kan geleiden zonder te smelten.$B$BIn Winterspring heb ik een imp ontmoet die allerlei exotische spullen verkocht. Hij had een elementaire staaf die perfect zou zijn. Ik kan mezelf nu wel voor mijn kop slaan dat ik hem niet gekocht heb.$B$BHij woont in een grot bij de ingang van Darkwhisper Gorge. Sluip daar naar binnen en probeer hem te vinden.$B$BZorg dat hij je maar veertig goud laat betalen; dat is de prijs die hij mij noemde!",
  o = "Zoek een imp in een grot bij de ingang van Darkwhisper Gorge in het zuiden van Winterspring, koop een Fel Elemental Rod en keer terug naar Mux Manascrambler in Gadgetzan.",
  p = "Heb je al geluk gehad met het vinden van de imp in Darkwhisper Gorge?",
  c = "Het is je gelukt! Deze staaf is perfect. Nu alles nog in elkaar zetten...",
  g = { {"louche", "shady, shifty"}, {"handelaar", "merchant, trader"}, {"kern", "core"}, {"staaf", "rod"}, {"geleiden", "to conduct, to channel"}, {"smelten", "to melt"}, {"allerlei", "all kinds of"}, {"exotische", "exotic (exotisch)"}, {"elementaire", "elemental (elementair)"}, {"mezelf voor mijn kop slaan", "to kick myself, to be angry at myself"}, {"sluip", "sneak (sluipen)"}, {"noemde", "named, quoted (noemen)"}, {"in elkaar zetten", "to put together, to assemble"} },
},

[9268] = { en = "War at Sea", tier = 4,
  t = "Oorlog op zee",
  p = "Wil je weer vrienden worden met de goblins van Tanaris, $N? We hebben materiaal nodig voor zeilen en kanonnen om onze oude vijanden te bevechten: de Bloodsail Buccaneers. Breng me mageweave en strong flux, dan zijn we op weg om je overtredingen te vergeven.",
  c = "Ga zo door, $N. Wij goblins vergeten niet zo makkelijk!",
